#!/usr/bin/env bash
# ResearchHub — import backlogu z audytu VPS i funkcji produktu, 2026-10-13.
# 61 szczegółowych definicji; snapshot: 50 nowych i 11 istniejących Task ID.
# Domyślnie: IgorK834/researchhub. Wszystkie odczyty obejmują issues otwarte i zamknięte.
# Wymagania: Bash >=3.2, GitHub CLI gh (sprawdzono 2.93.0), gh auth login.
# Podgląd: bash scripts/github/import-vps-backlog.sh --dry-run
# Import:  bash scripts/github/import-vps-backlog.sh
# --repo owner/repo pozwala świadomie wybrać inne repozytorium.
# Powtórny import pomija istniejące Task ID. Nie uruchamiaj równoległych importów.
# --force aktualizuje kolory/opisy etykiet zgodnie z szablonem użytkownika.
# Skrypt nie edytuje, nie zamyka i nie otwiera ponownie istniejących issues.
# Nie stosuje heredoców; każda komenda gh jest jednowierszowa.
set -Eeuo pipefail

REPOSITORY="IgorK834/researchhub"
DRY_RUN=0
CREATED_COUNT=0
SKIPPED_COUNT=0
MILESTONE_CREATED_COUNT=0

usage() {
  printf '%s\n' 'Użycie: bash scripts/github/import-vps-backlog.sh [--dry-run] [--repo owner/repo]' '  --dry-run: pobiera aktualny stan GitHub i wypisuje plan bez mutacji.' '  --repo: jawnie wskazuje repozytorium docelowe.' '  --help: pokazuje tę pomoc.'
}

while (( $# > 0 )); do
  case "$1" in
    --dry-run) DRY_RUN=1; shift ;;
    --repo) if (( $# < 2 )); then printf '%s\n' 'Brak owner/repo po --repo.' >&2; exit 2; fi; REPOSITORY="$2"; shift 2 ;;
    --help|-h) usage; exit 0 ;;
    *) printf 'Nieznany argument: %s\n' "$1" >&2; usage >&2; exit 2 ;;
  esac
done

if [[ ! "$REPOSITORY" =~ ^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$ ]]; then
  printf '%s\n' 'Repozytorium musi mieć postać owner/repo.' >&2
  exit 2
fi
if ! command -v gh >/dev/null 2>&1; then
  printf '%s\n' 'Brak GitHub CLI gh. Zainstaluj gh i wykonaj gh auth login.' >&2
  exit 1
fi
export GH_REPO="$REPOSITORY"
trap 'printf "Import przerwany (wiersz %s). Po usunięciu przyczyny ponownie uruchom skrypt; istniejące Task ID zostaną pominięte.\n" "$LINENO" >&2' ERR

# Wrapper blokuje mutacje w --dry-run i normalizuje kolor #hex do formatu CLI.
gh() {
  if (( DRY_RUN == 1 )) && [[ "$1 $2" == "label create" || "$1 $2" == "issue create" || "$1 $2" == "api repos/:owner/:repo/milestones" ]]; then
    local argument previous="" name=""
    for argument in "$@"; do
      if [[ "$previous" == "--title" ]]; then name="$argument"; break; fi
      if [[ "$argument" == title=* ]]; then name="${argument#title=}"; break; fi
      previous="$argument"
    done
    if [[ "$1 $2" == "label create" ]]; then name="$3"; fi
    printf '[DRY-RUN] %s %s: %s\n' "$1" "$2" "$name"
    return 0
  fi
  if [[ "$1 $2" == "label create" ]]; then
    local token expect_color=0
    local -a normalized_args=()
    for token in "$@"; do
      if (( expect_color == 1 )); then token="${token#\#}"; expect_color=0; fi
      normalized_args+=("$token")
      if [[ "$token" == "--color" ]]; then expect_color=1; fi
    done
    command gh "${normalized_args[@]}"
    return
  fi
  command gh "$@"
}

gh auth status >/dev/null
RESOLVED_REPOSITORY=$(gh repo view "$REPOSITORY" --json nameWithOwner --jq '.nameWithOwner')
if [[ "$(printf '%s' "$RESOLVED_REPOSITORY" | tr '[:upper:]' '[:lower:]')" != "$(printf '%s' "$REPOSITORY" | tr '[:upper:]' '[:lower:]')" ]]; then
  printf 'Nieoczekiwane repozytorium: %s\n' "$RESOLVED_REPOSITORY" >&2
  exit 1
fi
ISSUE_ROWS=$(gh api --paginate 'repos/:owner/:repo/issues?state=all&per_page=100' --jq '.[] | select(has("pull_request") | not) | [.number,.state,.title] | @tsv')
MILESTONE_ROWS=$(gh api --paginate 'repos/:owner/:repo/milestones?state=all&per_page=100' --jq '.[] | [.number,.title,.state] | @tsv')

# Wszystkie kontrole konfliktów milestone kończą się przed pierwszą mutacją.
validate_milestone() {
  local epic="$1" expected="$2" number title state
  while IFS=$'\t' read -r number title state; do
    [[ -z "$number" ]] && continue
    if [[ "$title" == "Epic ${epic}: "* && "$title" != "$expected" ]]; then
      printf 'Konflikt numeracji Epic %s: istnieje "%s", oczekiwano "%s". Zaktualizuj definicje przed importem.\n' "$epic" "$title" "$expected" >&2
      exit 1
    fi
    if [[ "$title" == "$expected" && "$state" != "open" ]]; then
      printf 'Milestone "%s" jest zamknięty. Wybierz otwarty milestone przed importem.\n' "$expected" >&2
      exit 1
    fi
  done < <(printf '%s\n' "$MILESTONE_ROWS")
}

should_create_milestone() {
  local expected="$1" number title state
  while IFS=$'\t' read -r number title state; do
    if [[ "$title" == "$expected" ]]; then
      printf '[POMIŃ MILESTONE] %s\n' "$expected"
      return 1
    fi
  done < <(printf '%s\n' "$MILESTONE_ROWS")
  return 0
}

should_create_issue() {
  local id="$1" number state title
  while IFS=$'\t' read -r number state title; do
    if [[ "$title" == "[Task ${id}]" || "$title" == "[Task ${id}] "* ]]; then
      printf '[POMIŃ ISSUE] Task %s: #%s (%s) — %s\n' "$id" "$number" "$state" "$title"
      (( SKIPPED_COUNT += 1 ))
      return 1
    fi
  done < <(printf '%s\n' "$ISSUE_ROWS")
  return 0
}

printf 'Repozytorium: %s | tryb: %s\n' "$REPOSITORY" "$([[ "$DRY_RUN" == 1 ]] && printf 'podgląd' || printf 'import')"
validate_milestone "3" "Epic 3: Frontend Foundation"
validate_milestone "24" "Epic 24: Advanced Source and Research Workflows"
validate_milestone "25" "Epic 25: Cross-Cutting Testing"
validate_milestone "26" "Epic 26: Developer Experience and Documentation"
validate_milestone "28" "Epic 28: Demo Kit and Portfolio Presentation"
validate_milestone "30" "Epic 30: Enterprise Account and Operations Features"
validate_milestone "31" "Epic 31: Wdrożenie demo na VPS"
validate_milestone "32" "Epic 32: Kontrola kosztów i nadużyć"
validate_milestone "33" "Epic 33: Utrzymanie i odzyskiwanie VPS"
validate_milestone "34" "Epic 34: Jakość i gotowość wydania"
validate_milestone "35" "Epic 35: Rozszerzone narzędzia badawcze"
validate_milestone "36" "Epic 36: Współpraca i cykl pracy"
validate_milestone "37" "Epic 37: Administracja organizacji"

